// A bar list whose scale is its own largest value, and no JavaScript computes it: the values are laid out as marks in one
// `auto` grid column, so the browser's own maximum sizes the column; a query container in that column reads its width back as
// a number (`round(100cqw / 1px)` into a registered `@property`) and every bar divides by it. A counter prints the number,
// because `content` cannot interpolate a custom property. Where container units are missing there are no bars — the numbers
// are the text of the list either way, so the table is still read.
import type { JSX } from "@solidjs/web";
import * as css from "cssints" with { type: "cssints" };
import { For } from "solid-js";

import "./scale.css";
import { t } from "./theme.ts" with { type: "cssints" };

/** One value: what it is called and its number, which is also the bar's length. */
export interface ScaleItem {
  readonly label: string;
  readonly value: number;
}

export interface ScaleProps {
  /** The values, in reading order; the largest one sets the scale. */
  readonly items: ReadonlyArray<ScaleItem>;
  /** The figure's caption, which is also the chart's name. */
  readonly label: string;
  readonly class?: string | undefined;
}

const rootClass = css.cn(css.display("grid"), css.gap(t.space._2), css.width("100%"));

const captionClass = css.cn(css.fontSize(t.font.sizeSm), css.color(t.color.muted));

// The computation's furniture: one `auto` column, its width the largest mark. `inline-grid` keeps the calculation as narrow as
// its answer instead of stretching across the page, and the marks are zero-high blocks whose width is the value in px.
const rulerClass = css.cn(
  css.display("inline-grid"),
  css.gridTemplateColumns("auto"),
  css.justifyItems("stretch"),
  css.width("max-content"),
);

const markClass = css.cn(css.blockSize("0"), css.margin("0"));

// The query container: a grid item stretched to the column, and `container-type` means its own content never widens it, so it
// measures the marks and not the chart inside it.
const probeClass = css.cn(css.containerType("inline-size"), css.minInlineSize("0"));

// Where the number is read and printed. `--scale` is set from a plain inline style (a dynamic value is inline, as everywhere),
// and it inherits from here down into the bars.
const gaugeClass = css.cn(css.display("grid"), css.gap(t.space._1));

const listClass = css.cn(
  css.display("grid"),
  css.gap(t.space._1),
  css.margin("0"),
  css.padding("0"),
  css.listStyle("none"),
);

const rowClass = css.cn(
  css.display("grid"),
  css.gridTemplateColumns("7rem 1fr auto"),
  css.alignItems("center"),
  css.gap(t.space._2),
  css.fontSize(t.font.sizeSm),
);

const nameClass = css.cn(css.color(t.color.muted), css.overflowWrap("anywhere"));

const trackClass = css.cn(
  css.display("block"),
  css.blockSize(t.space._2),
  css.borderRadius("999px"),
  css.bg(t.color.buttonBackground),
  css.overflow("hidden"),
  // without container units there is no scale to divide by: a bar of no length would be a guess, so there is no bar
  css.supports("not (width: 1cqw)")(css.display("none")),
);

// The one place the number is used: the value's share of the largest one, which is the whole chart's arithmetic.
const barClass = css.cn(
  css.display("block"),
  css.blockSize("100%"),
  css.bg(t.color.highlight),
  css.inlineSize("calc(var(--value) / var(--scale) * 100%)"),
);

const numberClass = css.cn(css.fontVariantNumeric("tabular-nums"), css.textAlign("end"));

const readoutClass = css.cn(
  css.display("flex"),
  css.alignItems("baseline"),
  css.gap(t.space._1),
  css.fontSize(t.font.sizeSm),
  css.color(t.color.muted),
  // the printed number comes from the counter below; without a scale it would print 0
  css.supports("not (width: 1cqw)")(css.display("none")),
);

// A counter is how a number is printed: `content` takes a counter, not a custom property, so the value is reset into one.
const printClass = css.cn(
  css.counterReset("result var(--scale)"),
  css.before(css.content("counter(result)")),
  css.color(t.color.text),
  css.fontVariantNumeric("tabular-nums"),
);

/**
 * A bar list scaled by its own largest value, computed by layout rather than by a script.
 *
 * The marks are the values as widths (`value` px), laid out in one `auto` grid column: the grid algorithm finds the widest to
 * place them, and the query container beside them reads that width back as a number — `round(100cqw / 1px)` into the
 * registered `--scale` — which every bar divides its own `--value` by. Nothing is compared in a formula and nothing is
 * measured by hand; adding a value adds work for the browser, not a term.
 *
 * Two things are raw: `scale.css` registers the property (a global, per-name thing, where cssints's unit is a class), and the
 * read is an inline style (a value computed by the browser, not by the build).
 */
export const Scale = (props: ScaleProps): JSX.Element => (
  <figure data-part="scale" class={css.cn(rootClass, props.class)}>
    <figcaption class={captionClass}>{props.label}</figcaption>
    <div data-part="scale-ruler" class={rulerClass}>
      <For each={props.items}>
        {(item) => (
          <span
            data-part="scale-mark"
            class={markClass}
            style={{ "inline-size": `${item.value}px` }}
            aria-hidden="true"
          />
        )}
      </For>
      <div data-part="scale-probe" class={probeClass}>
        <div
          data-part="scale-gauge"
          class={gaugeClass}
          style={{ "--scale": "round(100cqw / 1px)" }}
        >
          <ol data-part="scale-list" class={listClass}>
            <For each={props.items}>
              {(item) => (
                <li data-part="scale-row" class={rowClass} style={{ "--value": `${item.value}` }}>
                  <span class={nameClass}>{item.label}</span>
                  <span data-part="scale-track" class={trackClass} aria-hidden="true">
                    <span data-part="scale-bar" class={barClass} />
                  </span>
                  <span class={numberClass}>{item.value}</span>
                </li>
              )}
            </For>
          </ol>
          <p class={readoutClass}>
            <span>Scale</span>
            <output data-part="scale-print" class={printClass} />
          </p>
        </div>
      </div>
    </div>
  </figure>
);

/* The typed number the whole component divides by. A registration is global and per name, while cssints's unit is a class, so
   it is a sheet: `@property` turns the custom property into an <integer> at the place it is set, and a counter can print it. */
@property --scale {
  syntax: "<integer>";
  inherits: true;
  initial-value: 0;
}

import { look } from "@cssints/mise-en-mode" with { type: "cssints" };
import { check, createGlobalTheme, createTokens, media } from "cssints" with { type: "cssints" };

import { darkTheme, forcedColorsTheme, lightTokens } from "./tokens.ts";

// The theme the starters are written against: one lightness scale, one hue and one chroma per
// colour family, and the semantic colours made of them. The data lives in tokens.ts, so the
// registry can compile it to a plain theme.css without the cssints plugin; this module is the
// same theme for the components and the demo page, with the contrast gate.
const t = createTokens(lightTokens);

// The dark mode is the lightness scale turned over, so every step and every colour made of it follows: the text is still
// gray-1200, it is just a light gray now. The page and the surface are the reference's own dark values, and the popover shadow
// deepens because a shadow on a dark page reads as a smudge.
createGlobalTheme(t, media("(prefers-color-scheme: dark)"), darkTheme);

// The same dark look as a scope a page can ask for: `<div data-mode="dark">` moves every token inside it, and a surface or a
// frame under it follows without a prop. It is a mise-en-mode look, so it is in the `app` layer: a host's `author` or `viewer`
// look over the same marker wins without a specificity trick, and `data-mode="dark/color"` moves the colours alone. The media
// query above stays a global theme: a look is a `data-mode` scope, and the system preference is not one.
look(t, "dark", "app", darkTheme);

// One preset, because the theme is neutral: the reference's indigo, as its two numbers. The others are in its theme.css.
createGlobalTheme(t, '[data-tint="indigo"]', {
  hue: { tint: "284.23" },
  chroma: { tint: "0.25049" },
});

// On a dense screen (200dpi and up) the targets grow: the spacing steps and the text with them, as in the reference.
createGlobalTheme(t, media("(min-resolution: 200dpi)"), {
  space: { base: "calc(0.25rem * 1.25)" },
  font: { sizeSm: "0.9375rem", size: "1.0625rem", sizeLg: "1.25rem" },
});

// Windows high contrast mode throws the theme away and paints the system's own colours; forced-colors makes that explicit,
// since a component that reads a token here gets the system colour rather than the tint.
createGlobalTheme(t, media("(forced-colors: active)"), forcedColorsTheme);

// The pairs a reader meets on every page: body text, the second level of text, and a link on a card. Both modes and every
// theme above are checked (the preset too, since it sets the tokens the link is made of), and a ratio under the floor fails
// the build. 7 for text and 4.5 for the rest are the WCAG 2.x AAA and AA floors.
check.contrast(t.color.text, t.color.page, { min: 7 }); // the tabs skin's selected label
check.contrast(t.color.muted, t.color.page, { min: 4.5 }); // its unselected label
check.contrast(t.color.link, t.color.surface, { min: 4.5 });
check.contrast(t.color.placeholder, t.color.page, { min: 4.5 });
check.contrast(t.color.onHighlight, t.color.highlight, { min: 4.5 });
// The active tab's underline is a graphic against the page: 3 is the WCAG 1.4.11 floor for non-text contrast. The dark
// mode is the closest (3.55:1 without the preset, 3.17:1 with indigo), so a lighter highlight would break it.
check.contrast(t.color.highlight, t.color.page, { min: 3 });
// The focus ring is a graphic, not text: 3 is the WCAG 1.4.11 floor for a non-text contrast.
check.contrast(t.color.focusRing, t.color.page, { min: 3 }); // the tabs skin's ring

export { t };

// The scale's conformance: the number the bars divide by is read out of layout, not computed in script. The test reads it off
// the registered property, off the counter that prints it and off the bars themselves, and it reads the values as text —
// which is what remains where container units are missing.
import { render } from "@solidjs/web";
import type { JSX } from "@solidjs/web";
import { afterEach, describe, expect, it } from "vite-plus/test";

import { Scale, type ScaleItem } from "./scale.tsx";

const ITEMS: ReadonlyArray<ScaleItem> = [
  { label: "us-east", value: 420 },
  { label: "eu-west", value: 310 },
  { label: "ap-south", value: 96 },
  { label: "sa-east", value: 42 },
];

const mounted: Array<() => void> = [];

afterEach(() => {
  for (const dispose of mounted.splice(0)) {
    dispose();
  }
});

const mount = (items: ReadonlyArray<ScaleItem> = ITEMS): HTMLElement => {
  const host = document.createElement("div");
  document.body.append(host);
  const dispose = render(() => <Scale items={items} label="By region" />, host);
  mounted.push(() => {
    dispose();
    host.remove();
  });
  return host;
};

const part = <T extends Element>(host: HTMLElement, name: string): T =>
  host.querySelector<T>(`[data-part="${name}"]`)!;

const bars = (host: HTMLElement): HTMLElement[] => [
  ...host.querySelectorAll<HTMLElement>('[data-part="scale-bar"]'),
];

const tracks = (host: HTMLElement): HTMLElement[] => [
  ...host.querySelectorAll<HTMLElement>('[data-part="scale-track"]'),
];

const share = (host: HTMLElement, index: number): number =>
  Number.parseFloat(getComputedStyle(bars(host)[index]!).inlineSize) /
  Number.parseFloat(getComputedStyle(tracks(host)[index]!).inlineSize);

describe("Scale", () => {
  it("reads the largest value out of layout, and the bars divide by it", () => {
    // the division of a length by a length is what makes the read possible: a browser without it has no scale at all
    if (!CSS.supports("width", "1cqw")) {
      return;
    }
    const host = mount();
    // the number is the registered <integer>, computed by the query container: the largest value, in px
    const gauge = part<HTMLElement>(host, "scale-gauge");
    expect(getComputedStyle(gauge).getPropertyValue("--scale").trim()).toBe("420");
    // and the counter prints that number: `content` takes a counter, not a custom property
    const printed = part<HTMLElement>(host, "scale-print");
    expect(getComputedStyle(printed).counterReset).toBe("result 420");

    // the bars are the values' shares of the largest one
    expect(share(host, 0)).toBeCloseTo(1, 2);
    expect(share(host, 1)).toBeCloseTo(310 / 420, 2);
    expect(share(host, 3)).toBeCloseTo(42 / 420, 2);
  });

  it("moves the scale with a new largest value, and nothing else changes", () => {
    if (!CSS.supports("width", "1cqw")) {
      return;
    }
    const host = mount([...ITEMS, { label: "af-south", value: 900 }]);
    const gauge = part<HTMLElement>(host, "scale-gauge");
    expect(getComputedStyle(gauge).getPropertyValue("--scale").trim()).toBe("900");
    expect(share(host, 0)).toBeCloseTo(420 / 900, 2);
  });

  it("states every number as text, which is the fallback as well as the table", () => {
    const host = mount();
    const list = part<HTMLElement>(host, "scale-list");
    expect(list.textContent).toContain("us-east");
    expect(list.textContent).toContain("420");
    // the bars are decoration over those numbers, and the marks that measure are decoration too
    expect(part(host, "scale-track").getAttribute("aria-hidden")).toBe("true");
    expect(host.querySelectorAll('[data-part="scale-mark"]')).toHaveLength(ITEMS.length);
    expect(host.querySelector('[data-part="scale-mark"]')!.getAttribute("aria-hidden")).toBe(
      "true",
    );
    // the figure is named, so a reader knows what the numbers are
    expect(host.querySelector("figcaption")?.textContent).toBe("By region");
  });
});

import solid from "@solidjs/vite-plugin";
import cssints, { targets } from "cssints/vite";
import { defineConfig } from "vite-plus";
import { playwright } from "vite-plus/test/browser-playwright";

// The conformance test a starter arrives with runs in a real Chromium: the scenario walk needs a
// real DOM and Solid 2's reactivity, not a simulated one.
export default defineConfig({
  // `evaluation.inline`: a browser-mode runner inlines everything as ESM, so the plugin's own
  // evaluation server keeps the framework's packages inlined (Solid resolves its client build by
  // them) and the rest external (Node loads their CJS). Without it, a click's target resolves
  // against a second copy of Solid and the walk reads a state the page never changed.
  plugins: [
    cssints({ evaluation: { inline: ["solid-js", "@solidjs/web", "@solidjs/signals"] } }),
    solid(),
  ],
  css: { transformer: "lightningcss", lightningcss: { targets } },
  // The plugin adds `import derived from "cssints/derived"` to a client module after the dep
  // scanner has run; pre-bundling it here is what keeps that from reloading the page mid-test.
  optimizeDeps: { include: ["cssints/derived"] },
  test: {
    // a browser test has no app entry: the sheet of the modules the test imports arrives through
    // `virtual:cssints.css`, and vitest drops CSS imports unless it is told to process them
    css: true,
    // the sheet is loaded by the test's imports, not before them
    setupFiles: ["src/sheet.ts"],
    include: ["src/components/ui/**/*.browser.test.tsx"],
    browser: {
      enabled: true,
      provider: playwright(),
      headless: true,
      viewport: { width: 1280, height: 1024 },
      instances: [{ browser: "chromium" }],
      // The default waits 60 s for a worker's iframe to come up, which a busy machine (or a CI runner with a dozen other
      // jobs) misses: the run then fails as `the iframe did not become ready` with no test having run. Nothing about a
      // test gets longer; this is the browser starting.
      connectTimeout: 120_000,
      // the iframe ready timeout is read from the config's own env, not from the process that started the run
      env: { VITEST_BROWSER_IFRAME_TIMEOUT: "120000" },
    },
  },
});

// The engine's sheet for a browser test: its content is the CSS of the modules transformed so far, so it is loaded once the
// test file's imports are in (in `beforeAll`, not as a static import: vitest resolves the graph as it goes, and a sheet loaded
// first is just the `@layer` statement). A component's conformance test clicks its parts, so the sheet has to be there.
import { beforeAll } from "vite-plus/test";

beforeAll(async () => {
  await import("virtual:cssints.css");
});
